Now implement slug.go. Use strings.Fields + strings.ToLower + strings.Join.

Package comment already exists in greet.go, so no package doc needed in slug.go.

```go
package greeter

import "strings"

// Slug 把名字转成可用作页面锚点的 URL 友好 slug：
// 字母统一小写，连续空白折成单个连字符，首尾不留连字符。
func Slug(name string) string {
	fields := strings.Fields(name)
	for i, f := range fields {
		fields[i] = strings.ToLower(f)
	}
	return strings.Join(fields, "-")
}
```

This is minimal. strings.Fields handles all Unicode whitespace.

Now the test file. Table-driven.

```go
package greeter

import "testing"

func TestSlug(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"simple", "Hello World", "hello-world"},
		{"case folded", "MiXeD CaSe", "mixed-case"},
		{"already lower", "ada lovelace", "ada-lovelace"},
		{"leading trailing", "  Hello World  ", "hello-world"},
		{"collapse runs", "a \t\n  b", "a-b"},
		{"empty", "", ""},
		{"blank only", " \t\n ", ""},
		{"single word", "Ada", "ada"},
		{"cjk kept", "张三 李四", "张三-李四"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Slug(tt.in); got != tt.want {
				t.Fatalf("Slug(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}

func TestSlugCaseInsensitive(t *testing.T) {
	if a, b := Slug("Ada Lovelace"), Slug("ada lovelace"); a != b {
		t.Fatalf("case variants differ: %q vs %q", a, b)
	}
}
```

