package greeter

import "strings"

// Slug 把名字转成可用作页面锚点的 URL 友好 slug：
// 字母统一小写，连续空白折成单个连字符，首尾不留连字符。
func Slug(name string) string {
	fields := strings.Fields(name)
	for i, f := range fields {
		fields[i] = strings.ToLower(f)
	}
	return strings.Join(fields, "-")
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"simple", "Hello World", "hello-world"},
		{"case folded", "MiXeD CaSe", "mixed-case"},
		{"already lower", "ada lovelace", "ada-lovelace"},
		{"leading and trailing blanks", "  Hello World  ", "hello-world"},
		{"collapse blank runs", "a \t\n  b", "a-b"},
		{"single word", "Ada", "ada"},
		{"empty", "", ""},
		{"blank only", " \t\n ", ""},
		{"non-blank kept as is", "张三 李四", "张三-李四"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Slug(tt.in); got != tt.want {
				t.Fatalf("Slug(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}

func TestSlugCaseInsensitive(t *testing.T) {
	if got, want := Slug("Ada Lovelace"), Slug("ada lovelace"); got != want {
		t.Fatalf("case variants differ: %q vs %q", got, want)
	}
}
